-- 055. Фархад: тексты под озвучку (проверка voice-checker 25.11): «Валентина-апа» → «Валентина Петровна», без «уже», «потом»,
-- «звонил», «АО», омографов; «Пятьсот» → «Пять бумажек по сто». Только текст; audio_url и условия сохраняются.
begin;
update characters set fixed_questions = jsonb_set(fixed_questions, '{0,a}', to_jsonb('"— Друг, дорогой. Просто друг. Двадцать лет за этим столом. Игорь у меня в госснабе начинал, инженером. Мальчишка совсем, глаза горят… — Улыбается. — После кооператив вместе открыли. Год девяносто второй. А дальше жизнь развела. Ну, бывает. Так бывает, слушай."'::json #>> '{}')) where id = '5b4c1ece-ba00-50d6-9113-73e03e05ccd8';
update characters set fixed_questions = jsonb_set(fixed_questions, '{2,a}', to_jsonb('"— Олжас? — Фархад кашляет. Глухо, долго. Вытирает губы платком. — Хороший мальчик. Из аула. Сын моей двоюродной сестры. Мешки таскает на Зелёном, в общаге живёт. Я ему: учись, дорогой. А он мне: аке, деньги нужны. — Разводит руками. — Ну что я ему скажу? Сам такой был. — Пауза. — Его не трогай, дорогой. Он тут ни при чём, слышишь?"'::json #>> '{}')) where id = '5b4c1ece-ba00-50d6-9113-73e03e05ccd8';
update characters set fixed_questions = jsonb_set(fixed_questions, '{3,a}', to_jsonb('"— Похитили?.. — Долго молчит. Садится. — И Валентина Петровна мне ни слова. Двадцать лет — и ни слова. Ни слова, дорогой… — Трёт лицо ладонью. — Где был. Я же говорил тебе. Дома, в «Орбите». Один, Зарина у родни в Ташкенте. Свет у нас отключили, сидел при свечке. Чай пил. Никуда не выходил. Кто ж знал, что в ту ночь…"'::json #>> '{}')) where id = '5b4c1ece-ba00-50d6-9113-73e03e05ccd8';
update characters set fixed_questions = jsonb_set(fixed_questions, '{4,a}', to_jsonb('"— Шмидтов? Знаю, как не знать. Хорошие люди. Уехали к своим, в Германию. Дом их продаю, помогаю. Сейчас каждый продаёт, дорогой. — Отмахивается. — Только я там с октября не был. Ключи покупателю отдал. Какому — не помню, слушай. У меня их десять было, покупателей. Десять."'::json #>> '{}')) where id = '5b4c1ece-ba00-50d6-9113-73e03e05ccd8';
update characters set reaction_rules = (select jsonb_agg(case when r->>'id' = 'R37' then jsonb_set(r, '{text}', to_jsonb('"Фархад отмахивается перевязанной рукой.\n— Конверт? Я принёс, да. Свои. От сердца. Похороны сейчас сам знаешь сколько… а Валентина Петровна одна. — Видит, что вы смотрите на бинт. — Это? Казан. Обжёгся. Не обращай внимания, дорогой. — Пауза. — Мы с Игорем давно помирились. Что было, то было. Зла не держу. В субботу у себя в «Орбите» сидел. Один, Зарина у родни в Ташкенте. Свет отключили, при свечке сидел. Кто ж знал, что он в ту ночь… — Не договаривает. — Ты её сегодня не мучай, дорогой. Она держится. Но это снаружи."'::json #>> '{}')) else r end) from jsonb_array_elements(reaction_rules) r) where id = '5b4c1ece-ba00-50d6-9113-73e03e05ccd8';
update characters set reaction_rules = (select jsonb_agg(case when r->>'id' = 'R77' then jsonb_set(r, '{text}', to_jsonb('"— Валентина Петровна переживает. Ей сейчас всякое кажется.\nСобака это. На базаре, у мясных рядов. Я же ей говорил.\n(прячет руку)"'::json #>> '{}')) else r end) from jsonb_array_elements(reaction_rules) r) where id = '5b4c1ece-ba00-50d6-9113-73e03e05ccd8';
update characters set reaction_rules = (select jsonb_agg(case when r->>'id' = 'R93' then jsonb_set(r, '{text}', to_jsonb('"— Похитили?.. — Перечитывает. Медленно. — Шестьдесят тысяч. И внучке грозили.\n(трёт лицо ладонью)\n— И Валентина Петровна молчала. Мне — ни слова. Двадцать лет за её столом, дорогой. Двадцать лет. — Пауза. — Боялась, значит. Правильно боялась. Сейчас время такое."'::json #>> '{}')) else r end) from jsonb_array_elements(reaction_rules) r) where id = '5b4c1ece-ba00-50d6-9113-73e03e05ccd8';
update characters set reaction_rules = (select jsonb_agg(case when r->>'id' = 'R182' then jsonb_set(r, '{text}', to_jsonb('"Фархад прячет руку в рукав.\n— Собака, казан… — Машет рукой. — Кан при понятых всё сказал. Что Валентина Петровна видела, то и было."'::json #>> '{}')) else r end) from jsonb_array_elements(reaction_rules) r) where id = '5b4c1ece-ba00-50d6-9113-73e03e05ccd8';
update characters set reaction_rules = (select jsonb_agg(case when r->>'id' = 'R07' then jsonb_set(r, '{text}', to_jsonb('"Фархад берёт протокол двумя руками. Левая кисть в бинте.\nЧитает долго, шевелит губами.\n— Угорел… Грелся, значит. Эх, Игорь, Игорь. — Поднимает глаза. — Мы с ним давно помирились, дорогой, ты не думай. Зла не держал. Дай бог каждому такого друга. — Замечает, куда вы смотрите. Приподнимает руку. — Это? Казан. Плов делал, обжёгся, как мальчишка. Заживёт. — Пауза. — А у нас в «Орбите» в субботу тоже свет отключили. Сидел один при свечке. Чай пил. Зарина моя у родни в Ташкенте, с четверга. Думал, от Игоря звонок будет, а он… — Разглаживает протокол ладонью. — Пойду к Валентине Петровне. Ей сейчас одной нельзя."'::json #>> '{}')) else r end) from jsonb_array_elements(reaction_rules) r) where id = '5b4c1ece-ba00-50d6-9113-73e03e05ccd8';
update characters set reaction_rules = (select jsonb_agg(case when r->>'id' = 'R35' then jsonb_set(r, '{text}', to_jsonb('"Фархад смотрит на протокол сравнения купюр. Лицо у него каменеет.\n— Это от сердца было. — Пауза. Совсем тихо: — Валентине Петровне не говори. Как человека прошу. Двадцать лет я за её столом… Пусть думает, что от сердца. Пусть думает. — Прячет руки в рукава. Смотрит мимо вас, на дверь. — Больше ничего не скажу. Делай свою работу, дорогой."'::json #>> '{}')) else r end) from jsonb_array_elements(reaction_rules) r) where id = '5b4c1ece-ba00-50d6-9113-73e03e05ccd8';
update characters set reaction_rules = (select jsonb_agg(case when r->>'id' = 'R178' then jsonb_set(r, '{text}', to_jsonb('"— Шестьдесят просили. Сорок дали. — Трёт лицо ладонью. — Даше никто бы ничего не сделал. Я её пугал, чтоб молчала. Валентине Петровне скажи."'::json #>> '{}')) else r end) from jsonb_array_elements(reaction_rules) r) where id = '5b4c1ece-ba00-50d6-9113-73e03e05ccd8';
update characters set reaction_rules = (select jsonb_agg(case when r->>'id' = 'R223' then jsonb_set(r, '{text}', to_jsonb('"— Из тех денег. Знаю. — Пауза. — Валентине Петровне не говори, как человека прошу. Хоть это."'::json #>> '{}')) else r end) from jsonb_array_elements(reaction_rules) r) where id = '5b4c1ece-ba00-50d6-9113-73e03e05ccd8';
update characters set reaction_rules = (select jsonb_agg(case when r->>'id' = 'R31' then jsonb_set(r, '{text}', to_jsonb('"Перед Фархадом запись КПП за двадцать восьмое октября и показания Ахметова.\nОн долго молчит. Потом тихо, уже без «дорогой»:\n— Помирились… Нет. Не помирились. Я за него сидел. Полтора года. Ты знаешь, что такое полтора года, когда тебе сорок семь? — Пауза. — Он обещал: доля твоя, семья твоя под присмотром. Я вышел. А базы моей нет. Есть их фирма. Я к нему пришёл по-человечески. А он мне — «завскладом». При своём счетоводе, при нём. — Кашляет. — Да. Обиделся. Только обиду в милицию не носят, слушай. Обида — не преступление."'::json #>> '{}')) else r end) from jsonb_array_elements(reaction_rules) r) where id = '5b4c1ece-ba00-50d6-9113-73e03e05ccd8';
update characters set reaction_rules = (select jsonb_agg(case when r->>'id' = 'R36' then jsonb_set(r, '{text}', to_jsonb('"Олжаса уводят. Фархад смотрит на закрытую дверь. Потом говорит медленно, по-отечески. В последний раз.\n— Мальчика пожалей. Он не знал. Я ему сказал: никто не пострадает. Я и сам тогда верил. — Пауза. — Слушай сюда. Ерлану я долг списал. За четверги. Больше он ничего не знал. Игоря мы взяли. Я долю хотел. Свою. Только долю, понимаешь? — Кашляет. — А тут Олжас приходит: он тебя узнал. И я понял. Живой — он меня посадит. А Зарина одна останется. С моими долгами. Они к ней приходили, к дочке моей… — Долго молчит. — Я его сам. Один. После на Кок-Тобе отвёз, на его же машине. Мотор завёл. Вниз пешком. Внизу частника поймал, номера не помню, не спрашивай. Часть денег кредитору отдал. Остальное ты нашёл. — Поднимает глаза. — Пощады не прошу. Дочку только не трогайте."'::json #>> '{}')) else r end) from jsonb_array_elements(reaction_rules) r) where id = '5b4c1ece-ba00-50d6-9113-73e03e05ccd8';
update characters set reaction_rules = (select jsonb_agg(case when r->>'id' = 'R76' then jsonb_set(r, '{text}', to_jsonb('"— Олжас? Племянник. Сын сестры.\nИз аула приехал, на базаре мешки таскает. Я ему помогаю, как могу. Мальчик хороший.\n(резко)\nЕго не трогайте. Он тут ни при чём."'::json #>> '{}')) else r end) from jsonb_array_elements(reaction_rules) r) where id = '5b4c1ece-ba00-50d6-9113-73e03e05ccd8';
update characters set reaction_rules = (select jsonb_agg(case when r->>'id' = 'R228' then jsonb_set(r, '{text}', to_jsonb('"— Олжас. Сын сестры. — Голос садится. — Я его втянул. Он не знал, на что идёт. Пожалей мальчика."'::json #>> '{}')) else r end) from jsonb_array_elements(reaction_rules) r) where id = '5b4c1ece-ba00-50d6-9113-73e03e05ccd8';
update characters set reaction_rules = (select jsonb_agg(case when r->>'id' = 'R92' then jsonb_set(r, '{text}', to_jsonb('"— «Волга»… — Улыбается, по-отечески. — Дорогой, белых «Волг» в Алма-Ате как грязи. И фара у каждой второй разбита, дороги у нас какие, сам видишь.\n(пауза)\n— На базу я в октябре заходил. Это каждый знает, я не прятался. А в четверг стоять, на ворота смотреть… Зачем мне? Я не мальчишка."'::json #>> '{}')) else r end) from jsonb_array_elements(reaction_rules) r) where id = '5b4c1ece-ba00-50d6-9113-73e03e05ccd8';
update characters set reaction_rules = (select jsonb_agg(case when r->>'id' = 'R94' then jsonb_set(r, '{text}', to_jsonb('"— Выкуп… — Лицо не меняется. Только пальцы перестают мять шапку. — Данияр, значит, отвёз.\n(пауза)\n— И копии снял. Со всех. — Усмехается углом рта. — Счетовод. Он и на поминках салфетки пересчитает. — Кладёт лист на стол, разглаживает ладонью. — Хорошо, что снял. Пусть ищут теперь, кто взял. Пусть ищут."'::json #>> '{}')) else r end) from jsonb_array_elements(reaction_rules) r) where id = '5b4c1ece-ba00-50d6-9113-73e03e05ccd8';
update characters set reaction_rules = (select jsonb_agg(case when r->>'id' = 'R95' then jsonb_set(r, '{text}', to_jsonb('"— Шмидта телефон? — Пауза. Длиннее, чем нужно. — Дом Шмидтов я продаю, да. По доверенности. Хорошие люди, уехали к своим.\n(отмахивается)\n— Телефон не отключили, видишь. Кто там ходит, кто смотрит, кто по телефону говорит — я за каждым не хожу, дорогой. Покупателей много. Спроси у них."'::json #>> '{}')) else r end) from jsonb_array_elements(reaction_rules) r) where id = '5b4c1ece-ba00-50d6-9113-73e03e05ccd8';
update characters set reaction_rules = (select jsonb_agg(case when r->>'id' = 'R96' then jsonb_set(r, '{text}', to_jsonb('"Фархад читает выписку. Возвращает. Двумя руками, вежливо.\n— «Ф.». Одна буква, дорогой. Фёдор, Фарида, Фарид. Полгорода на «Ф».\n(пауза)\n— Что за четверг, что в силе — спроси того, кому отправляли. По одной букве людей не сажают. Не при Сталине живём."'::json #>> '{}')) else r end) from jsonb_array_elements(reaction_rules) r) where id = '5b4c1ece-ba00-50d6-9113-73e03e05ccd8';
update characters set reaction_rules = (select jsonb_agg(case when r->>'id' = 'R100' then jsonb_set(r, '{text}', to_jsonb('"Кабинет. Фархад смотрит на свои ботинки в целлофане. Долго.\n— Мои. Сорок третий. Порез — гвоздём, на базаре зацепил.\n(кашляет, глухо)\n— У Игоря на Кок-Тобе я сто раз был, дорогой. Двадцать лет. — Пауза. — Когда был — не помню. Ты бы помнил, когда в гостях был?"'::json #>> '{}')) else r end) from jsonb_array_elements(reaction_rules) r) where id = '5b4c1ece-ba00-50d6-9113-73e03e05ccd8';
update characters set reaction_rules = (select jsonb_agg(case when r->>'id' = 'R176' then jsonb_set(r, '{text}', to_jsonb('"— Пять бумажек по сто. Из тех денег, да. — Долго молчит. — Хотел, чтоб ей на похороны хватило. Глупость сделал, дорогой. Ей не показывай."'::json #>> '{}')) else r end) from jsonb_array_elements(reaction_rules) r) where id = '5b4c1ece-ba00-50d6-9113-73e03e05ccd8';
update characters set reaction_rules = (select jsonb_agg(case when r->>'id' = 'R180' then jsonb_set(r, '{text}', to_jsonb('"— Ерлан правду говорит. Долг списал за четверги. — Пауза. — Он думал, разговор будет. Он больше ничего не знал, дорогой. Это я тебе говорил."'::json #>> '{}')) else r end) from jsonb_array_elements(reaction_rules) r) where id = '5b4c1ece-ba00-50d6-9113-73e03e05ccd8';
update characters set reaction_rules = (select jsonb_agg(case when r->>'id' = 'R215' then jsonb_set(r, '{text}', to_jsonb('"Фархад смотрит на голую кисть.\n— Игорь. Ногтями. — Пауза. — Не собака и не казан. Это я тебе говорил."'::json #>> '{}')) else r end) from jsonb_array_elements(reaction_rules) r) where id = '5b4c1ece-ba00-50d6-9113-73e03e05ccd8';
update characters set reaction_rules = (select jsonb_agg(case when r->>'id' = 'R186' then jsonb_set(r, '{text}', to_jsonb('"— Мои. Сорок третий. — Кашляет, глухо. — Я там был в ту ночь. Говорил же."'::json #>> '{}')) else r end) from jsonb_array_elements(reaction_rules) r) where id = '5b4c1ece-ba00-50d6-9113-73e03e05ccd8';
update characters set reaction_rules = (select jsonb_agg(case when r->>'id' = 'R221' then jsonb_set(r, '{text}', to_jsonb('"— Игорь. Ногтями. Говорил же."'::json #>> '{}')) else r end) from jsonb_array_elements(reaction_rules) r) where id = '5b4c1ece-ba00-50d6-9113-73e03e05ccd8';
update characters set reaction_rules = (select jsonb_agg(case when r->>'id' = 'R225' then jsonb_set(r, '{text}', to_jsonb('"— Мои. В них и был там, у гаража. Мыл — не отмыл. — Пауза. — Говорил же."'::json #>> '{}')) else r end) from jsonb_array_elements(reaction_rules) r) where id = '5b4c1ece-ba00-50d6-9113-73e03e05ccd8';
update characters set reaction_rules = (select jsonb_agg(case when r->>'id' = 'R189' then jsonb_set(r, '{text}', to_jsonb('"— «Ф.» — это я. Ерлану отправлял. Говорил же, дорогой."'::json #>> '{}')) else r end) from jsonb_array_elements(reaction_rules) r) where id = '5b4c1ece-ba00-50d6-9113-73e03e05ccd8';
update characters set reaction_rules = (select jsonb_agg(case when r->>'id' = 'R216' then jsonb_set(r, '{text}', to_jsonb('"— Телефон Шмидтов. — Пауза. — Оттуда я никого не набирал, дорогой. Кто набирал — у того и спрашивай."'::json #>> '{}')) else r end) from jsonb_array_elements(reaction_rules) r) where id = '5b4c1ece-ba00-50d6-9113-73e03e05ccd8';
update characters set reaction_rules = (select jsonb_agg(case when r->>'id' = 'R217' then jsonb_set(r, '{text}', to_jsonb('"— Олжас оттуда номер набирал. Я не знал. — Пауза. — Знал бы — не дал. Дурак мальчишка."'::json #>> '{}')) else r end) from jsonb_array_elements(reaction_rules) r) where id = '5b4c1ece-ba00-50d6-9113-73e03e05ccd8';
update characters set reaction_rules = (select jsonb_agg(case when r->>'id' = 'R218' then jsonb_set(r, '{text}', to_jsonb('"Фархад на протокол не смотрит.\n— Угорел, написали. — Пауза. — Я тебе про субботу всё сказал, дорогой. Больше по этой бумаге нечего."'::json #>> '{}')) else r end) from jsonb_array_elements(reaction_rules) r) where id = '5b4c1ece-ba00-50d6-9113-73e03e05ccd8';
commit;
